GLuint vertex_program(bool canonical){const auto source=mtoon_renderer_vertex(false);const auto *s=source.c_str();GLuint shader=glCreateShader(GL_VERTEX_SHADER);glShaderSource(shader,1,&s,nullptr);glCompileShader(shader);GLint ok=0;glGetShaderiv(shader,GL_COMPILE_STATUS,&ok);if(!ok)throw std::runtime_error("Actual production before vertex shader failed compile");GLuint p=glCreateProgram();glAttachShader(p,shader);const char *varyings[]={"world",canonical?"canonical_n":"source_n",canonical?"canonical_t":"source_t",canonical?"canonical_b":"source_b"};glTransformFeedbackVaryings(p,4,varyings,GL_INTERLEAVED_ATTRIBS);glLinkProgram(p);glDeleteShader(shader);glGetProgramiv(p,GL_LINK_STATUS,&ok);if(!ok)throw std::runtime_error("Actual production vertex feedback failed link");return p;}
struct Columns {std::vector<Vec3> positions,normals;std::vector<std::array<float,4>> tangents;};
Columns before_columns(const MeshSnapshot&s,uint64_t id,bool canonical){const auto range=std::find_if(s.ranges.begin(),s.ranges.end(),[&](const auto&r){return r.object==id;});if(range==s.ranges.end()||!range->source_frame)throw std::runtime_error("Actual source frame snapshot unavailable");Columns out;for(size_t c=0;c<range->count;++c){const size_t logical=range->paint_winding_reversed?c/3*3+(c%3==1?2:c%3==2?1:0):c;const auto v=s.mesh.indices.at(range->first+logical);out.positions.push_back(s.mesh.positions.at(v));out.normals.push_back((canonical?s.canonical_normals:s.source_normals).at(v));out.tangents.push_back((canonical?s.tangents:s.source_tangents).at(v));}return out;}
std::vector<std::array<Vec3,4>> before_gpu(GLuint program,const Columns &c,const detail::VertexStageMatrices&m,detail::VertexBitangentPolicy policy,bool canonical){struct V{Vec3 p,n;std::array<float,4>t;};std::vector<V> vertices;for(size_t i=0;i<c.positions.size();++i)vertices.push_back({c.positions[i],c.normals[i],c.tangents[i]});GLuint vao=0,buffer=0,feedback=0;glGenVertexArrays(1,&vao);glBindVertexArray(vao);glGenBuffers(1,&buffer);glBindBuffer(GL_ARRAY_BUFFER,buffer);glBufferData(GL_ARRAY_BUFFER,vertices.size()*sizeof(V),vertices.data(),GL_STATIC_DRAW);for(auto [location,count,offset]:{std::tuple{0,3,offsetof(V,p)},std::tuple{canonical?9:7,3,offsetof(V,n)},std::tuple{canonical?5:8,4,offsetof(V,t)}}){glVertexAttribPointer(location,count,GL_FLOAT,GL_FALSE,sizeof(V),reinterpret_cast<void*>(offset));glEnableVertexAttribArray(location);}std::vector<std::array<Vec3,4>> values(c.positions.size());glGenBuffers(1,&feedback);glBindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,feedback);glBufferData(GL_TRANSFORM_FEEDBACK_BUFFER,values.size()*sizeof(values[0]),nullptr,GL_STREAM_READ);glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER,0,feedback);glUseProgram(program);glUniformMatrix4fv(glGetUniformLocation(program,"model"),1,GL_FALSE,m.model.data());glUniformMatrix4fv(glGetUniformLocation(program,"mvp"),1,GL_FALSE,m.model.data());glUniformMatrix3fv(glGetUniformLocation(program,"normal_model"),1,GL_FALSE,m.normal.data());glUniform1i(glGetUniformLocation(program,"affine_motion"),1);glUniform1i(glGetUniformLocation(program,"source_frame"),1);glUniform1i(glGetUniformLocation(program,"canonical_frame"),canonical?1:0);glUniform1i(glGetUniformLocation(program,"prepared_pbr_frame"),policy==detail::VertexBitangentPolicy::UnitCross);glUniform1f(glGetUniformLocation(program,"model_hand"),m.hand);glEnable(GL_RASTERIZER_DISCARD);glBeginTransformFeedback(GL_POINTS);glDrawArrays(GL_POINTS,0,GLsizei(vertices.size()));glEndTransformFeedback();glDisable(GL_RASTERIZER_DISCARD);glGetBufferSubData(GL_TRANSFORM_FEEDBACK_BUFFER,0,values.size()*sizeof(values[0]),values.data());glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER,0,0);glDeleteBuffers(1,&feedback);glDeleteBuffers(1,&buffer);glDeleteVertexArrays(1,&vao);return values;}
